style.css:
/* Cambia el color de fondo a rosa */
body {
    background-color: #ffc0cb !important;
}
/* Cambia el color del texto dentro de los inputs y textareas a rosado */
input, textarea {
    color: #ff69b4 !important;
}

/* También puedes cambiar el color del borde del cuadro de texto a rosado */
input, textarea {
    border: 2px solid #ff69b4 !important;
}

/* Aplica una fuente linda y redondeada */
body, p, h1, h2, h3, h4, h5, h6 {
    font-family: 'Comic Sans MS', cursive, sans-serif !important;
}

/* Cambia los botones a un estilo estético */
button {
    background-color: #ff69b4 !important;
    border-radius: 10px !important;
    color: white !important;
    border: none !important;
}
